From b4effa8017f4445b1909eb3d2bb4afd7f73ffc09 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 16:22:29 +0100
Subject: [PATCH] openconnect: put the keyboard focus in the login form's first
 empty field

PasswordField is a container around a line edit, so setFocus() on it left
the focus on the container, and the form was focused before being added to
the dialog, which drops the focus. Add a focus proxy and focus it later.

BUG: 506021
---
 libs/editor/widgets/passwordfield.cpp |  1 +
 vpn/openconnect/openconnectauth.cpp   | 12 ++++++++----
 2 files changed, 9 insertions(+), 4 deletions(-)

diff --git a/libs/editor/widgets/passwordfield.cpp b/libs/editor/widgets/passwordfield.cpp
index 654f2a8b9..343c0ddb1 100644
--- a/libs/editor/widgets/passwordfield.cpp
+++ b/libs/editor/widgets/passwordfield.cpp
@@ -35,6 +35,7 @@ PasswordField::PasswordField(QWidget *parent, Qt::WindowFlags f)
     }

     m_layout->addWidget(m_passwordField);
+    setFocusProxy(m_passwordField);

     m_passwordOptionsMenu->setSizeAdjustPolicy(QComboBox::AdjustToContentsOnFirstShow);

diff --git a/vpn/openconnect/openconnectauth.cpp b/vpn/openconnect/openconnectauth.cpp
index a02b55b67..dc82cfbfc 100644
--- a/vpn/openconnect/openconnectauth.cpp
+++ b/vpn/openconnect/openconnectauth.cpp
@@ -706,7 +706,7 @@ void OpenconnectAuthWidget::processAuthForm(struct oc_auth_form *form)
     struct oc_form_opt *opt;
     auto layout = new QFormLayout();
     QSizePolicy policy(QSizePolicy::Expanding, QSizePolicy::Fixed);
-    bool focusSet = false;
+    QWidget *firstEmptyField = nullptr;
     for (opt = form->opts; opt; opt = opt->next) {
         if (opt->type == OC_FORM_OPT_HIDDEN || IGNORE_OPT(opt)) {
             continue;
@@ -723,9 +723,8 @@ void OpenconnectAuthWidget::processAuthForm(struct oc_auth_form *form)
             if (opt->type == OC_FORM_OPT_PASSWORD) {
                 le->setPasswordModeEnabled(true);
             }
-            if (!focusSet && le->text().isEmpty()) {
-                le->setFocus(Qt::OtherFocusReason);
-                focusSet = true;
+            if (!firstEmptyField && le->text().isEmpty()) {
+                firstEmptyField = le;
             }
             widget = qobject_cast<QWidget *>(le);
         } else if (opt->type == OC_FORM_OPT_SELECT) {
@@ -781,6 +780,11 @@ void OpenconnectAuthWidget::processAuthForm(struct oc_auth_form *form)
     d->ui.loginBoxLayout->addLayout(layout);
     d->passwordFormIndex = d->ui.loginBoxLayout->count() - 1;

+    // Only now: adding the layout reparents the fields, which clears their focus
+    if (firstEmptyField) {
+        firstEmptyField->setFocus(Qt::OtherFocusReason);
+    }
+
     auto box = new QDialogButtonBox(this);
     QPushButton *btn = box->addButton(QDialogButtonBox::Ok);
     btn->setText(i18nc("Verb, to proceed with login", "Login"));
-- 
